const backends = ['10.0.0.1', '10.0.0.2', '10.0.0.3'];
const healthy = new Set(backends);

async function ping(host) {
  try {
    const res = await fetch(`http://${host}/health`, { signal: AbortSignal.timeout(800) });
    return res.ok;
  } catch {
    return false;
  }
}

setInterval(async () => {
  for (const host of backends) {
    (await ping(host) ? healthy.add(host) : healthy.delete(host));
  }
}, 5000);

export function pickBackend() {
  const pool = backends.filter((h) => healthy.has(h));
  if (!pool.length) throw new Error('no redundant path left');
  return pool[Math.floor(Math.random() * pool.length)];
}
